    transferUser: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                id: string;
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    /**
                     * Format: uuid
                     * @description Move a Sales Executive to this ASM
                     */
                    asmId: string;
                    /**
                     * Format: uuid
                     * @description Move an ASM to this zone (Admin only)
                     */
                    zoneId: string;
                };
            };
        };
        responses: {
            /** @description The person after the move. The message says how many partners stayed with the old ASM. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "success": true,
                     *       "message": "Staff moved. 1 partner(s) stayed with the old ASM, unassigned.",
                     *       "data": {
                     *         "id": "01a1c439-7524-720c-830c-0bea75e664b0",
                     *         "name": "TEST SE 1",
                     *         "status": "active"
                     *       }
                     *     }
                     */
                    "application/json": components["schemas"]["SuccessEnvelope"] & {
                        data?: components["schemas"]["Staff"];
                    };
                };
            };
            400: components["responses"]["ValidationError"];
            401: components["responses"]["NotLoggedIn"];
            403: components["responses"]["Forbidden"];
            /** @description The person or the new ASM/zone was not found, or is outside what you can see */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorEnvelope"];
                };
            };
            /** @description A rule stops the move (`CONFLICT`, `OPEN_REQUESTS` with `details.openRequests`, or `OPEN_TASKS` with `details.openTasks`) */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorEnvelope"];
                };
            };
        };
    };
    getMyTeam: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description The ASM's team */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "success": true,
                     *       "data": {
                     *         "summary": {
                     *           "salesExecutives": 4,
                     *           "partners": 3,
                     *           "unassignedPartners": 1,
                     *           "openRequests": 2,
                     *           "pendingTasks": 5,
                     *           "overdueTasks": 1
                     *         },
                     *         "salesExecutives": [
                     *           {
                     *             "id": "01a1c439-7524-720c-830c-0bea75e664b0",
                     *             "name": "TEST SE 1",
                     *             "phone": "919000000131",
                     *             "email": null,
                     *             "status": "active",
                     *             "createdAt": "2026-11-10T06:51:02.308Z",
                     *             "counts": {
                     *               "partners": 1,
                     *               "openRequests": 1,
                     *               "pendingTasks": 3,
                     *               "overdueTasks": 1
                     *             }
                     *           }
                     *         ]
                     *       }
                     *     }
                     */
                    "application/json": components["schemas"]["SuccessEnvelope"] & {
                        data?: {
                            summary: {
                                salesExecutives: number;
                                partners: number;
                                /** @description Partners with no Sales Executive */
                                unassignedPartners: number;
                                /** @description Open requests handled by me or my Sales Executives */
                                openRequests: number;
                                /** @description Unfinished tasks given to me or my Sales Executives */
                                pendingTasks: number;
                                /** @description Of those, past their due day */
                                overdueTasks: number;
                            };
                            salesExecutives: {
                                /** Format: uuid */
                                id: string;
                                name: string | null;
                                phone: string;
                                email: string | null;
                                /** @enum {string} */
                                status: "active" | "suspended";
                                /** Format: date-time */
                                createdAt: string;
                                counts: {
                                    partners: number;
                                    /** @description Open requests this Sales Executive handles */
                                    openRequests: number;
                                    /** @description Unfinished tasks given to this Sales Executive */
                                    pendingTasks: number;
                                    /** @description Of those */
                                    overdueTasks: number;
                                };
                            }[];
                        };
                    };
                };
            };
            401: components["responses"]["NotLoggedIn"];
            403: components["responses"]["Forbidden"];
        };
    };
